1	/**
2	 * Slug generation and validation, shared by organization creation, project
3	 * creation and the "is this slug free?" checks in both the Zod schemas and the
4	 * repositories. One implementation so the client preview and the server
5	 * insertion can never disagree.
6	 */
7	
8	export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
9	
10	export const SLUG_MIN_LENGTH = 2;
11	export const SLUG_MAX_LENGTH = 48;
12	
13	/** Slugs the router or marketing pages already claim. */
14	export const RESERVED_SLUGS: readonly string[] = [
15	  "admin",
16	  "api",
17	  "auth",
18	  "billing",
19	  "blog",
20	  "changelog",
21	  "dashboard",
22	  "docs",
23	  "help",
24	  "login",
25	  "logout",
26	  "new",
27	  "pricing",
28	  "register",
29	  "settings",
30	  "static",
31	  "support",
32	  "taskflow",
33	  "www",
34	];
35	
36	/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
37	export function slugify(input: string): string {
38	  return input
39	    .normalize("NFKD")
40	    .replace(/[\u0300-\u036f]/g, "")
41	    .toLowerCase()
42	    .replace(/[^a-z0-9]+/g, "-")
43	    .replace(/^-+|-+$/g, "")
44	    .slice(0, SLUG_MAX_LENGTH)
45	    .replace(/-+$/g, "");
46	}
47	
48	export function isValidSlug(value: string): boolean {
49	  return (
50	    value.length >= SLUG_MIN_LENGTH &&
51	    value.length <= SLUG_MAX_LENGTH &&
52	    SLUG_PATTERN.test(value)
53	  );
54	}
55	
56	export function isReservedSlug(value: string): boolean {
57	  return RESERVED_SLUGS.includes(value);
58	}
59	
60	export class InvalidSlugError extends Error {
61	  readonly code = "validation_failed" as const;
62	
63	  constructor(readonly value: string, readonly reason: string) {
64	    super(`Invalid slug "${value}": ${reason}`);
65	    this.name = "InvalidSlugError";
66	  }
67	}
68	
69	export function assertValidSlug(value: string): void {
70	  if (!isValidSlug(value)) {
71	    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
72	  }
73	  if (isReservedSlug(value)) {
74	    throw new InvalidSlugError(value, "is reserved");
75	  }
76	}
77	
78	/**
79	 * Derives a slug from `input` that collides with nothing in `taken`, by
80	 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
81	 */
82	export function uniqueSlug(input: string, taken: Iterable<string>): string {
83	  const base = slugify(input) || "item";
84	  const used = new Set(taken);
85	  if (!used.has(base) && !isReservedSlug(base)) return base;
86	
87	  for (let suffix = 2; suffix < 1_000; suffix += 1) {
88	    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
89	    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
90	  }
91	  throw new InvalidSlugError(base, "exhausted unique suffixes");
92	}
93	
94	/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
95	export function projectKeyFromName(name: string): string {
96	  const words = name.trim().split(/\s+/).filter(Boolean);
97	  const letters =
98	    words.length >= 2
99	      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
100	      : (words[0] ?? "task").slice(0, 3);
